use super::*;
use semio_framework_value::{ToValue,FromValue,RetainedCloneGrant};
#[test]
fn native_text_codecs_match_utf8_corpus(){let value:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🧱️foundation/🔣️.json")).unwrap();for row in value["texts"].as_array().unwrap(){let source=row["unit"].as_str().unwrap().repeat(row["repeat"].as_u64().unwrap() as usize);assert_eq!(source.len(),row["bytes"].as_u64().unwrap()as usize);let parsed=UiText::try_from_str(&source);assert_eq!(parsed.is_some(),row["valid"].as_bool().unwrap());assert_eq!(serde_json::from_value::<UiText>(serde_json::json!(source)).is_ok(),parsed.is_some());if let Some(text)=parsed{assert_eq!(serde_json::to_value(&text).unwrap(),serde_json::json!(source));assert_eq!(UiText::from_value(text.to_value()).unwrap(),text);assert_eq!(text.as_ref(),source);assert_eq!(text.to_string(),source);assert_eq!(format!("{:?}",text),format!("{:?}",source));}else{let clipped=UiText::clipped(&source);assert!(clipped.len()<=UI_TEXT_MAX_BYTES);assert!(clipped.as_str().ends_with(UI_TEXT_CLIP_MARK));assert!(source.starts_with(clipped.as_str().strip_suffix(UI_TEXT_CLIP_MARK).unwrap()));}}}
#[test]
fn original_text_copy_and_retirement_obey_exact_byte_grants(){let source=Box::new(UiText::try_from_str("Grüße🧬").unwrap());let mut copy=UiTextOriginalCopy::new(&source);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let mut completed=None;for _ in 0..source.len()+2{let(result,progress)=copy.step(&source,grant).unwrap();assert!(progress.copied_bytes<=1);if result.is_some(){completed=result;break;}}assert_eq!(completed.as_ref(),Some(source.as_ref()));let foreign=Box::new(source.as_ref().clone());let mut original=UiTextOriginalCopy::new(&source);assert!(original.step(&foreign,grant).is_err());let mut target=UiText::default();assert_eq!(target.copy_prefix_from(&source,0).unwrap(),(false,0));while target.len()<source.len(){let(_,bytes)=target.copy_prefix_from(&source,1).unwrap();assert_eq!(bytes,1);}assert_eq!(target,*source);assert_eq!(target.retire_bytes(0),0);let mut released=0;while !target.is_empty(){released+=target.retire_bytes(1);}assert_eq!(released,source.len());assert!(target.comparison_bytes().is_empty());}
